function createEnv(sdk) {
  var GROUND = 420;
  var START_Y = 65;
  var FLIGHT_LIMIT = 260;
  var terms = [0, 0, 0, 0, 0, 0];
  var obs = [0, 0, 0, 0, 0, 0];
  var rng, x, y, vx, vy, padX, padHalf, tick, done;
  var lastMain = false, lastSide = 0;
  var starsX = [], starsY = [];

  function progress() {
    return sdk.clamp((y - START_Y) / (GROUND - START_Y), 0, 1);
  }

  function gravity() {
    return sdk.clamp(0.026 + 0.000055 * tick + 0.012 * progress(), 0.026, 0.052);
  }

  function updatePad() {
    padHalf = 52 - 24 * progress();
  }

  function setAction(action) {
    var a = action | 0;
    if (a < 0 || a > 5) a = 0;
    lastMain = a === 1 || a === 4 || a === 5;
    lastSide = a === 2 || a === 4 ? -1 : (a === 3 || a === 5 ? 1 : 0);
  }

  return {
    reset: function (seed) {
      rng = sdk.rng(seed);
      x = rng.range(300, 500);
      y = START_Y;
      vx = 0;
      vy = 0;
      padX = sdk.clamp(x + rng.range(-115, 115), 170, 630);
      tick = 0;
      done = false;
      lastMain = false;
      lastSide = 0;
      updatePad();
      for (var i = 0; i < terms.length; i++) terms[i] = 0;
      starsX = [];
      starsY = [];
      for (var j = 0; j < 28; j++) {
        starsX.push(rng.range(20, 780));
        starsY.push(rng.range(20, 320));
      }
    },

    step: function (action) {
      if (done) return;

      setAction(action);
      var oldY = y;
      var g = gravity();

      vy += g;
      if (lastMain) vy -= 0.082;
      vx += lastSide * 0.024;
      vx *= 0.995;
      vy = sdk.clamp(vy, -4.5, 7.5);
      vx = sdk.clamp(vx, -5.5, 5.5);
      x += vx;
      y += vy;
      tick++;
      updatePad();

      terms[0] += 1 / 30;
      terms[2] += Math.max(0, y - oldY) / (GROUND - START_Y);
      if (lastMain || lastSide !== 0) terms[5] += 1 / 30;

      var dx = Math.abs(x - padX);
      var align = sdk.clamp(1 - dx / (padHalf + 120), 0, 1);
      var lateralControl = sdk.clamp(1 - Math.abs(vx) / 5, 0, 1);
      var descentControl = sdk.clamp((vy - 0.15) / 1.0, 0, 1) *
        sdk.clamp((4.2 - vy) / 2.8, 0, 1);
      terms[1] += align * lateralControl * descentControl / 30;

      if (y >= GROUND) {
        if (dx <= padHalf - 8 && Math.abs(vx) <= 1.25 && vy >= 0 && vy <= 1.5) {
          terms[3] += 1;
        } else {
          terms[4] += 1;
        }
        done = true;
      } else if (x < 18 || x > 782 || y < 18 || tick >= FLIGHT_LIMIT) {
        terms[4] += 1;
        done = true;
      }
    },

    observe: function () {
      var alt = (GROUND - y) / (GROUND - START_Y);
      var g = gravity();
      obs[0] = sdk.clamp((x - padX) / 200, -1, 1);
      obs[1] = sdk.clamp(2 * alt - 1, -1, 1);
      obs[2] = sdk.clamp(vx / 5.5, -1, 1);
      obs[3] = sdk.clamp(vy / 7.5, -1, 1);
      obs[4] = sdk.clamp((padHalf - 40) / 20, -1, 1);
      obs[5] = sdk.clamp((g - 0.039) / 0.02, -1, 1);
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      if (!ghost) {
        draw.clear(sdk.colors.bg);
        for (var i = 0; i < starsX.length; i++) {
          draw.circle(starsX[i], starsY[i], 1.5, sdk.colors.dim);
        }
        draw.line(0, GROUND + 18, 800, GROUND + 18, sdk.colors.dim, 3);
        draw.line(padX - padHalf, GROUND, padX + padHalf, GROUND, sdk.colors.good, 6);
        draw.line(padX - padHalf, GROUND + 2, padX - padHalf - 10, GROUND + 12, sdk.colors.dim, 2);
        draw.line(padX + padHalf, GROUND + 2, padX + padHalf + 10, GROUND + 12, sdk.colors.dim, 2);
        draw.text("PAD", padX - 14, GROUND + 32, sdk.colors.dim, 12);
        draw.text("DOWN " + Math.max(0, vy).toFixed(1), 24, 30, sdk.colors.fg, 14);
      }

      if (lastMain) {
        draw.poly([x - 5, y + 12, x, y + 28, x + 5, y + 12], sdk.colors.warn, true);
      }
      if (lastSide < 0) {
        draw.poly([x - 12, y + 2, x - 25, y + 7, x - 12, y + 10], sdk.colors.warn, true);
      } else if (lastSide > 0) {
        draw.poly([x + 12, y + 2, x + 25, y + 7, x + 12, y + 10], sdk.colors.warn, true);
      }

      draw.poly([x - 12, y + 9, x - 9, y - 8, x, y - 14, x + 9, y - 8, x + 12, y + 9], sdk.colors.accent, true);
      draw.line(x - 8, y + 8, x - 14, y + 17, sdk.colors.fg, 2);
      draw.line(x + 8, y + 8, x + 14, y + 17, sdk.colors.fg, 2);
      draw.line(x - 16, y + 17, x - 11, y + 17, sdk.colors.fg, 2);
      draw.line(x + 11, y + 17, x + 16, y + 17, sdk.colors.fg, 2);
    },

    humanAct: function (input) {
      var up = input.held.has("ArrowUp");
      var left = input.held.has("ArrowLeft");
      var right = input.held.has("ArrowRight");
      if (left && !right) return up ? 4 : 2;
      if (right && !left) return up ? 5 : 3;
      return up ? 1 : 0;
    }
  };
}
